package com.rwi.myrepublic.nisa.internal;import com.rwi.myrepublic.nisa.NisaConfig;import java.io.IOException;import java.net.CookieManager;import java.net.URI;import java.net.http.HttpClient;import java.net.http.HttpRequest;import java.net.http.HttpResponse;import java.time.Duration;public class NisaMassProblemClient{private final NisaConfig config;private final HttpClient httpClient;private final NisaAuthClient authClient;public
NisaMassProblemClient(){this.config=NisaConfig.getInstance();this.httpClient=HttpClient.newBuilder().connectTimeout(Duration.ofMillis(config.getConnectionTimeout())).followRedirects(HttpClient.Redirect.NORMAL).cookieHandler(new CookieManager()).build();this.authClient=new NisaAuthClient(config,httpClient);}public String getMassProblemActiveCluster(String clusterCode)throws IOException,InterruptedException{String token=authClient.getToken();String url=config.getApiBaseUrl()+
"/transaction/massproblem/active/cluster";String body= "{\"cluster\":\""+escapeJson(clusterCode)+ "\"}";HttpRequest request=HttpRequest.newBuilder().uri(URI.create(url)).header("Authorization", "Bearer "+token).header("Content-Type", "application/json").timeout(Duration.ofMillis(config.getRequestTimeout())).method("GET",HttpRequest.BodyPublishers.ofString(body)).build();HttpResponse<String>response=httpClient.send(request,HttpResponse.BodyHandlers.ofString());int
statusCode=response.statusCode();String responseBody=response.body();if(statusCode!=200){throw new IOException("NISA mass problem API returned HTTP "+statusCode+ " | Body: "+responseBody);}return responseBody;}public String searchMassProblemByArea(String area)throws IOException,InterruptedException{String token=authClient.getToken();String url=config.getApiBaseUrl()+ "/transaction/massproblem/active/cluster/search";String body= "{\"cluster\":\""+escapeJson(area)+ "\"}";HttpRequest
request=HttpRequest.newBuilder().uri(URI.create(url)).header("Authorization", "Bearer "+token).header("Content-Type", "application/json").timeout(Duration.ofMillis(config.getRequestTimeout())).method("GET",HttpRequest.BodyPublishers.ofString(body)).build();HttpResponse<String>response=httpClient.send(request,HttpResponse.BodyHandlers.ofString());int statusCode=response.statusCode();String responseBody=response.body();if(statusCode!=200){throw new
IOException("NISA area search API returned HTTP "+statusCode+ " | Body: "+responseBody);}return responseBody;}private String escapeJson(String value){if(value==null)return "";return value.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n").replace("\r", "\\r").replace("\t", "\\t");}}